-- Chạy thủ công; không tự tái tạo bài tập khi khởi động.
BEGIN;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM practice_databases WHERE slug='quan-ly-sach-va-tac-gia') THEN RAISE EXCEPTION 'Book database not found'; END IF; END $$;
UPDATE practice_databases d SET exercises_count=(SELECT COUNT(*) FROM practice_exercises e WHERE e.database_id=d.id) WHERE d.slug='quan-ly-sach-va-tac-gia';
COMMIT;
