INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT 'ce77fd9c-4add-5275-b747-95038582eca0',d.id,'Danh sách sách và nhà xuất bản','Dùng INNER JOIN để liệt kê từng sách cùng nhà xuất bản; sắp xếp book_id tăng dần. Trả về các cột theo đúng thứ tự: book_id, title, publisher_name.','EASY','JOIN, SELECT',100,'["Dùng INNER JOIN để liệt kê từng sách cùng nhà xuất bản; sắp xếp book_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["book_id", "title", "publisher_name"]'::jsonb,'SELECT b.book_id, b.title, p.name AS publisher_name FROM books b JOIN publishers p ON p.publisher_id=b.publisher_id ORDER BY b.book_id',1 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT '880ae715-0ab5-510f-a944-9ce1675063b0',d.id,'Danh sách sách theo thể loại','Nối sách với thể loại; sắp xếp book_id tăng dần. Trả về các cột theo đúng thứ tự: book_id, title, category_name.','EASY','JOIN, SELECT',100,'["Nối sách với thể loại; sắp xếp book_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["book_id", "title", "category_name"]'::jsonb,'SELECT b.book_id,b.title,c.name AS category_name FROM books b JOIN categories c ON c.category_id=b.category_id ORDER BY b.book_id',2 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT 'edd2da36-07b0-5182-8c94-b7ba96508fbf',d.id,'Thông tin sách, thể loại và nhà xuất bản','Nối ba bảng để lấy thông tin từng sách; sắp xếp book_id tăng dần. Trả về các cột theo đúng thứ tự: book_id, title, category_name, publisher_name.','EASY','JOIN, SELECT',100,'["Nối ba bảng để lấy thông tin từng sách; sắp xếp book_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["book_id", "title", "category_name", "publisher_name"]'::jsonb,'SELECT b.book_id,b.title,c.name AS category_name,p.name AS publisher_name FROM books b JOIN categories c ON c.category_id=b.category_id JOIN publishers p ON p.publisher_id=b.publisher_id ORDER BY b.book_id',3 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT 'b1f9bbdd-49c9-5d15-85fa-83264dea6c23',d.id,'Tác giả của từng cuốn sách','Nối qua book_authors, mỗi dòng là một tác giả của sách; sắp xếp book_id rồi author_order tăng dần. Trả về các cột theo đúng thứ tự: book_id, title, author_name, author_order.','EASY','JOIN, MANY-TO-MANY',100,'["Nối qua book_authors, mỗi dòng là một tác giả của sách; sắp xếp book_id rồi author_order tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["book_id", "title", "author_name", "author_order"]'::jsonb,'SELECT b.book_id,b.title,a.full_name AS author_name,ba.author_order FROM books b JOIN book_authors ba ON ba.book_id=b.book_id JOIN authors a ON a.author_id=ba.author_id ORDER BY b.book_id,ba.author_order',4 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT 'bd90b5eb-9d94-5cb3-bc92-d6cbc0cdee16',d.id,'Sách thuộc thể loại Công nghệ','Nối books với categories và chỉ lấy thể loại Công nghệ; sắp xếp book_id tăng dần. Trả về các cột theo đúng thứ tự: book_id, title, price.','EASY','JOIN, WHERE',100,'["Nối books với categories và chỉ lấy thể loại Công nghệ; sắp xếp book_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["book_id", "title", "price"]'::jsonb,'SELECT b.book_id,b.title,b.price FROM books b JOIN categories c ON c.category_id=b.category_id WHERE c.name=''Công nghệ'' ORDER BY b.book_id',5 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT '0c79b3ab-72cc-5ae2-aeb6-d81e39efee10',d.id,'Sách của nhà xuất bản tại Hà Nội','Nối sách với nhà xuất bản, chỉ lấy city bằng Hà Nội; sắp xếp book_id tăng dần. Trả về các cột theo đúng thứ tự: book_id, title, publisher_name, city.','EASY','JOIN, WHERE',100,'["Nối sách với nhà xuất bản, chỉ lấy city bằng Hà Nội; sắp xếp book_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["book_id", "title", "publisher_name", "city"]'::jsonb,'SELECT b.book_id,b.title,p.name AS publisher_name,p.city FROM books b JOIN publishers p ON p.publisher_id=b.publisher_id WHERE p.city=''Hà Nội'' ORDER BY b.book_id',6 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT '7f3f2600-3af5-53da-8498-2c856ed54852',d.id,'Các sách do Nguyễn Minh An tham gia viết','Nối sách, bảng liên kết và tác giả để tìm sách của Nguyễn Minh An; sắp xếp book_id tăng dần. Trả về các cột theo đúng thứ tự: book_id, title, author_order.','EASY','JOIN, WHERE',100,'["Nối sách, bảng liên kết và tác giả để tìm sách của Nguyễn Minh An; sắp xếp book_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["book_id", "title", "author_order"]'::jsonb,'SELECT b.book_id,b.title,ba.author_order FROM books b JOIN book_authors ba ON ba.book_id=b.book_id JOIN authors a ON a.author_id=ba.author_id WHERE a.full_name=''Nguyễn Minh An'' ORDER BY b.book_id',7 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT 'be7f2470-4878-55aa-b437-b4829a97edae',d.id,'Tác giả đứng tên đầu tiên của mỗi sách','Chỉ lấy tác giả có author_order bằng 1; sắp xếp book_id tăng dần. Trả về các cột theo đúng thứ tự: book_id, title, author_name.','EASY','JOIN, WHERE',100,'["Chỉ lấy tác giả có author_order bằng 1; sắp xếp book_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["book_id", "title", "author_name"]'::jsonb,'SELECT b.book_id,b.title,a.full_name AS author_name FROM books b JOIN book_authors ba ON ba.book_id=b.book_id JOIN authors a ON a.author_id=ba.author_id WHERE ba.author_order=1 ORDER BY b.book_id',8 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT '1debc84f-82ce-5fab-ba50-1093cf05c74d',d.id,'Sách còn hàng có giá từ 120000 đồng','Nối sách với thể loại, lấy stock_quantity lớn hơn 0 và price từ 120000 trở lên; sắp xếp price giảm dần rồi book_id tăng dần. Trả về các cột theo đúng thứ tự: book_id, title, category_name, price, stock_quantity.','EASY','JOIN, WHERE, ORDER BY',100,'["Nối sách với thể loại, lấy stock_quantity lớn hơn 0 và price từ 120000 trở lên; sắp xếp price giảm dần rồi book_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["book_id", "title", "category_name", "price", "stock_quantity"]'::jsonb,'SELECT b.book_id,b.title,c.name AS category_name,b.price,b.stock_quantity FROM books b JOIN categories c ON c.category_id=b.category_id WHERE b.stock_quantity>0 AND b.price>=120000 ORDER BY b.price DESC,b.book_id',9 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT '43ee5582-906f-5092-9396-1bfc9d491b12',d.id,'Tất cả nhà xuất bản kể cả chưa có sách','Dùng LEFT JOIN từ publishers sang books, giữ cả nhà xuất bản chưa có sách với book_id và title là NULL; sắp xếp publisher_id rồi book_id tăng dần. Trả về các cột theo đúng thứ tự: publisher_id, publisher_name, book_id, title.','EASY','LEFT JOIN, NULL',100,'["Dùng LEFT JOIN từ publishers sang books, giữ cả nhà xuất bản chưa có sách với book_id và title là NULL; sắp xếp publisher_id rồi book_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["publisher_id", "publisher_name", "book_id", "title"]'::jsonb,'SELECT p.publisher_id,p.name AS publisher_name,b.book_id,b.title FROM publishers p LEFT JOIN books b ON b.publisher_id=p.publisher_id ORDER BY p.publisher_id,b.book_id',10 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT 'b5b55a5e-3a60-5ed9-ad48-061cc9621adb',d.id,'Đếm sách theo từng thể loại','Gom nhóm theo thể loại và đếm số sách, giữ cả thể loại chưa có sách; sắp xếp category_id tăng dần. Trả về các cột theo đúng thứ tự: category_id, category_name, book_count.','MEDIUM','GROUP BY, COUNT, LEFT JOIN',100,'["Gom nhóm theo thể loại và đếm số sách, giữ cả thể loại chưa có sách; sắp xếp category_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["category_id", "category_name", "book_count"]'::jsonb,'SELECT c.category_id,c.name AS category_name,COUNT(b.book_id) AS book_count FROM categories c LEFT JOIN books b ON b.category_id=c.category_id GROUP BY c.category_id,c.name ORDER BY c.category_id',11 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT '60310d32-7497-5f16-a4e2-d9bd6ed787c1',d.id,'Đếm sách của từng nhà xuất bản','Đếm số sách theo nhà xuất bản, bao gồm nhà xuất bản có 0 sách; sắp xếp publisher_id tăng dần. Trả về các cột theo đúng thứ tự: publisher_id, publisher_name, book_count.','MEDIUM','GROUP BY, COUNT, LEFT JOIN',100,'["Đếm số sách theo nhà xuất bản, bao gồm nhà xuất bản có 0 sách; sắp xếp publisher_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["publisher_id", "publisher_name", "book_count"]'::jsonb,'SELECT p.publisher_id,p.name AS publisher_name,COUNT(b.book_id) AS book_count FROM publishers p LEFT JOIN books b ON b.publisher_id=p.publisher_id GROUP BY p.publisher_id,p.name ORDER BY p.publisher_id',12 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT '7a097b52-7a0d-51d7-893d-b7d9887e05aa',d.id,'Giá trung bình theo thể loại','Tính giá trung bình của sách theo thể loại, làm tròn 2 chữ số thập phân; sắp xếp category_id tăng dần. Trả về các cột theo đúng thứ tự: category_id, category_name, average_price.','MEDIUM','GROUP BY, AVG, ROUND',100,'["Tính giá trung bình của sách theo thể loại, làm tròn 2 chữ số thập phân; sắp xếp category_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["category_id", "category_name", "average_price"]'::jsonb,'SELECT c.category_id,c.name AS category_name,ROUND(AVG(b.price),2) AS average_price FROM categories c JOIN books b ON b.category_id=c.category_id GROUP BY c.category_id,c.name ORDER BY c.category_id',13 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT '4753e9bd-0e7c-5134-bead-b751f66a6ac1',d.id,'Khoảng giá sách của từng nhà xuất bản','Tìm giá thấp nhất và cao nhất theo nhà xuất bản có sách; sắp xếp publisher_id tăng dần. Trả về các cột theo đúng thứ tự: publisher_id, publisher_name, min_price, max_price.','MEDIUM','GROUP BY, MIN, MAX',100,'["Tìm giá thấp nhất và cao nhất theo nhà xuất bản có sách; sắp xếp publisher_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["publisher_id", "publisher_name", "min_price", "max_price"]'::jsonb,'SELECT p.publisher_id,p.name AS publisher_name,MIN(b.price) AS min_price,MAX(b.price) AS max_price FROM publishers p JOIN books b ON b.publisher_id=p.publisher_id GROUP BY p.publisher_id,p.name ORDER BY p.publisher_id',14 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT '9b728a1d-5acc-5ca7-9f14-c572eba433fb',d.id,'Tổng tồn kho của từng thể loại','Cộng số lượng tồn kho theo thể loại; sắp xếp category_id tăng dần. Trả về các cột theo đúng thứ tự: category_id, category_name, total_stock.','MEDIUM','GROUP BY, SUM',100,'["Cộng số lượng tồn kho theo thể loại; sắp xếp category_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["category_id", "category_name", "total_stock"]'::jsonb,'SELECT c.category_id,c.name AS category_name,SUM(b.stock_quantity) AS total_stock FROM categories c JOIN books b ON b.category_id=c.category_id GROUP BY c.category_id,c.name ORDER BY c.category_id',15 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT 'c1bf4bc8-e1fe-549b-8e43-4464140c3e49',d.id,'Giá trị tồn kho theo nhà xuất bản','Tính tổng price nhân stock_quantity cho mỗi nhà xuất bản; giữ nhà xuất bản chưa có sách với tổng bằng 0; sắp xếp publisher_id tăng dần. Trả về các cột theo đúng thứ tự: publisher_id, publisher_name, inventory_value.','MEDIUM','GROUP BY, SUM, COALESCE',100,'["Tính tổng price nhân stock_quantity cho mỗi nhà xuất bản; giữ nhà xuất bản chưa có sách với tổng bằng 0; sắp xếp publisher_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["publisher_id", "publisher_name", "inventory_value"]'::jsonb,'SELECT p.publisher_id,p.name AS publisher_name,COALESCE(SUM(b.price*b.stock_quantity),0) AS inventory_value FROM publishers p LEFT JOIN books b ON b.publisher_id=p.publisher_id GROUP BY p.publisher_id,p.name ORDER BY p.publisher_id',16 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT '465fdce7-402c-5c86-9e50-3fe3e35558c4',d.id,'Số cuốn sách mỗi tác giả tham gia viết','Đếm số book_id khác nhau của từng tác giả, kể cả tác giả chưa có sách; sắp xếp author_id tăng dần. Trả về các cột theo đúng thứ tự: author_id, author_name, book_count.','MEDIUM','GROUP BY, COUNT DISTINCT',100,'["Đếm số book_id khác nhau của từng tác giả, kể cả tác giả chưa có sách; sắp xếp author_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["author_id", "author_name", "book_count"]'::jsonb,'SELECT a.author_id,a.full_name AS author_name,COUNT(DISTINCT ba.book_id) AS book_count FROM authors a LEFT JOIN book_authors ba ON ba.author_id=a.author_id GROUP BY a.author_id,a.full_name ORDER BY a.author_id',17 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT '4bc78eec-4882-58a7-8f73-f5a470e1932c',d.id,'Tìm những sách có từ hai tác giả','Gom nhóm theo sách và dùng HAVING để chỉ giữ sách có ít nhất 2 tác giả; sắp xếp book_id tăng dần. Trả về các cột theo đúng thứ tự: book_id, title, author_count.','MEDIUM','GROUP BY, HAVING, COUNT',100,'["Gom nhóm theo sách và dùng HAVING để chỉ giữ sách có ít nhất 2 tác giả; sắp xếp book_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["book_id", "title", "author_count"]'::jsonb,'SELECT b.book_id,b.title,COUNT(ba.author_id) AS author_count FROM books b JOIN book_authors ba ON ba.book_id=b.book_id GROUP BY b.book_id,b.title HAVING COUNT(ba.author_id)>=2 ORDER BY b.book_id',18 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT '609d3278-eac1-5312-b52b-b0e25938930f',d.id,'Nhà xuất bản có ít nhất bốn sách','Gom nhóm và lọc nhà xuất bản có ít nhất 4 sách bằng HAVING; sắp xếp publisher_id tăng dần. Trả về các cột theo đúng thứ tự: publisher_id, publisher_name, book_count.','MEDIUM','GROUP BY, HAVING, COUNT',100,'["Gom nhóm và lọc nhà xuất bản có ít nhất 4 sách bằng HAVING; sắp xếp publisher_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["publisher_id", "publisher_name", "book_count"]'::jsonb,'SELECT p.publisher_id,p.name AS publisher_name,COUNT(b.book_id) AS book_count FROM publishers p JOIN books b ON b.publisher_id=p.publisher_id GROUP BY p.publisher_id,p.name HAVING COUNT(b.book_id)>=4 ORDER BY p.publisher_id',19 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT '4f327a87-814f-529b-84e6-4fdc9fdb82e1',d.id,'Thống kê sách còn hàng và hết hàng theo thể loại','Dùng SUM kết hợp CASE để đếm số đầu sách còn hàng (stock_quantity > 0) và hết hàng (= 0) trong từng thể loại; sắp xếp category_id tăng dần. Trả về các cột theo đúng thứ tự: category_id, category_name, in_stock_count, out_of_stock_count.','MEDIUM','GROUP BY, SUM, CASE',100,'["Dùng SUM kết hợp CASE để đếm số đầu sách còn hàng (stock_quantity > 0) và hết hàng (= 0) trong từng thể loại; sắp xếp category_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["category_id", "category_name", "in_stock_count", "out_of_stock_count"]'::jsonb,'SELECT c.category_id,c.name AS category_name,SUM(CASE WHEN b.stock_quantity>0 THEN 1 ELSE 0 END) AS in_stock_count,SUM(CASE WHEN b.stock_quantity=0 THEN 1 ELSE 0 END) AS out_of_stock_count FROM categories c JOIN books b ON b.category_id=c.category_id GROUP BY c.category_id,c.name ORDER BY c.category_id',20 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT 'd18f2d76-0c46-5529-908b-944dfecebef4',d.id,'Sách có giá cao hơn giá trung bình toàn bộ sách','Dùng truy vấn con tính giá trung bình toàn bộ books và lấy sách có giá cao hơn mức đó; sắp xếp book_id tăng dần. Trả về các cột theo đúng thứ tự: book_id, title, price.','HARD','SUBQUERY, AVG',100,'["Dùng truy vấn con tính giá trung bình toàn bộ books và lấy sách có giá cao hơn mức đó; sắp xếp book_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["book_id", "title", "price"]'::jsonb,'SELECT book_id,title,price FROM books WHERE price>(SELECT AVG(price) FROM books) ORDER BY book_id',21 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT 'a3b3c8d9-fa99-5ea8-a059-efc4004460d2',d.id,'Sách đắt hơn mức trung bình cùng thể loại','Dùng truy vấn con tương quan để tìm sách có giá lớn hơn giá trung bình của chính thể loại đó; sắp xếp book_id tăng dần. Trả về các cột theo đúng thứ tự: book_id, title, category_id, price.','HARD','CORRELATED SUBQUERY, AVG',100,'["Dùng truy vấn con tương quan để tìm sách có giá lớn hơn giá trung bình của chính thể loại đó; sắp xếp book_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["book_id", "title", "category_id", "price"]'::jsonb,'SELECT b.book_id,b.title,b.category_id,b.price FROM books b WHERE b.price>(SELECT AVG(x.price) FROM books x WHERE x.category_id=b.category_id) ORDER BY b.book_id',22 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT '86afee48-623f-5391-a50e-532d5dedc726',d.id,'Sách đắt nhất trong mỗi thể loại','Dùng truy vấn con tìm giá lớn nhất theo thể loại, lấy tất cả sách đồng giá cao nhất; sắp xếp category_id rồi book_id tăng dần. Trả về các cột theo đúng thứ tự: book_id, title, category_id, price.','HARD','CORRELATED SUBQUERY, MAX',100,'["Dùng truy vấn con tìm giá lớn nhất theo thể loại, lấy tất cả sách đồng giá cao nhất; sắp xếp category_id rồi book_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["book_id", "title", "category_id", "price"]'::jsonb,'SELECT b.book_id,b.title,b.category_id,b.price FROM books b WHERE b.price=(SELECT MAX(x.price) FROM books x WHERE x.category_id=b.category_id) ORDER BY b.category_id,b.book_id',23 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT '3128570b-c8fa-5391-9304-8c072bca32de',d.id,'Nhà xuất bản chưa phát hành sách nào','Dùng NOT EXISTS để tìm nhà xuất bản không có sách; sắp xếp publisher_id tăng dần. Trả về các cột theo đúng thứ tự: publisher_id, publisher_name.','HARD','SUBQUERY, NOT EXISTS',100,'["Dùng NOT EXISTS để tìm nhà xuất bản không có sách; sắp xếp publisher_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["publisher_id", "publisher_name"]'::jsonb,'SELECT p.publisher_id,p.name AS publisher_name FROM publishers p WHERE NOT EXISTS (SELECT 1 FROM books b WHERE b.publisher_id=p.publisher_id) ORDER BY p.publisher_id',24 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT '67b898b2-f5c0-5faf-8fe6-c6aff438296b',d.id,'Tác giả có sách thuộc thể loại Công nghệ','Dùng EXISTS với truy vấn con nối book_authors, books, categories; mỗi tác giả chỉ xuất hiện một lần; sắp xếp author_id tăng dần. Trả về các cột theo đúng thứ tự: author_id, author_name.','HARD','SUBQUERY, EXISTS, JOIN',100,'["Dùng EXISTS với truy vấn con nối book_authors, books, categories; mỗi tác giả chỉ xuất hiện một lần; sắp xếp author_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["author_id", "author_name"]'::jsonb,'SELECT a.author_id,a.full_name AS author_name FROM authors a WHERE EXISTS (SELECT 1 FROM book_authors ba JOIN books b ON b.book_id=ba.book_id JOIN categories c ON c.category_id=b.category_id WHERE ba.author_id=a.author_id AND c.name=''Công nghệ'') ORDER BY a.author_id',25 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT '00b037db-fedc-52ee-83f4-6741c1cbf85e',d.id,'Sách cùng nhà xuất bản với Thiết kế cơ sở dữ liệu','Dùng truy vấn con tìm nhà xuất bản của sách Thiết kế cơ sở dữ liệu rồi lấy các sách khác cùng nhà xuất bản; không lấy chính sách đó; sắp xếp book_id tăng dần. Trả về các cột theo đúng thứ tự: book_id, title, publisher_id.','HARD','SUBQUERY, IN',100,'["Dùng truy vấn con tìm nhà xuất bản của sách Thiết kế cơ sở dữ liệu rồi lấy các sách khác cùng nhà xuất bản; không lấy chính sách đó; sắp xếp book_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["book_id", "title", "publisher_id"]'::jsonb,'SELECT book_id,title,publisher_id FROM books WHERE publisher_id IN (SELECT publisher_id FROM books WHERE title=''Thiết kế cơ sở dữ liệu'') AND title<>''Thiết kế cơ sở dữ liệu'' ORDER BY book_id',26 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT 'a32bfd17-8278-5161-b8d2-c533f592783c',d.id,'Sách có giá cao hơn mọi sách thể loại Công nghệ','Dùng ALL với truy vấn con để tìm sách có giá lớn hơn mọi sách thuộc thể loại Công nghệ; sắp xếp book_id tăng dần. Trả về các cột theo đúng thứ tự: book_id, title, price.','HARD','SUBQUERY, ALL',100,'["Dùng ALL với truy vấn con để tìm sách có giá lớn hơn mọi sách thuộc thể loại Công nghệ; sắp xếp book_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["book_id", "title", "price"]'::jsonb,'SELECT b.book_id,b.title,b.price FROM books b WHERE b.price>ALL (SELECT x.price FROM books x JOIN categories c ON c.category_id=x.category_id WHERE c.name=''Công nghệ'') ORDER BY b.book_id',27 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT '6e4b1403-dd7c-5683-ac37-585961b45e25',d.id,'Sách có lượng tồn cao thứ hai phân biệt','Dùng truy vấn lồng MAX để tìm mức tồn kho lớn nhất nhỏ hơn mức cao nhất toàn bộ books, lấy tất cả sách có mức tồn đó; sắp xếp book_id tăng dần. Trả về các cột theo đúng thứ tự: book_id, title, stock_quantity.','HARD','NESTED SUBQUERY, MAX',100,'["Dùng truy vấn lồng MAX để tìm mức tồn kho lớn nhất nhỏ hơn mức cao nhất toàn bộ books, lấy tất cả sách có mức tồn đó; sắp xếp book_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["book_id", "title", "stock_quantity"]'::jsonb,'SELECT book_id,title,stock_quantity FROM books WHERE stock_quantity=(SELECT MAX(stock_quantity) FROM books WHERE stock_quantity<(SELECT MAX(stock_quantity) FROM books)) ORDER BY book_id',28 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT '90ea2f9d-dd88-5687-a730-620325b94859',d.id,'Nhà xuất bản có số sách cao hơn trung bình các nhà xuất bản','Dùng truy vấn con trong FROM để tính số sách mỗi nhà xuất bản (kể cả 0), sau đó so sánh số sách từng nhà xuất bản với trung bình của các số đếm này; sắp xếp publisher_id tăng dần. Trả về các cột theo đúng thứ tự: publisher_id, publisher_name, book_count.','HARD','SUBQUERY, DERIVED TABLE, GROUP BY',100,'["Dùng truy vấn con trong FROM để tính số sách mỗi nhà xuất bản (kể cả 0), sau đó so sánh số sách từng nhà xuất bản với trung bình của các số đếm này; sắp xếp publisher_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["publisher_id", "publisher_name", "book_count"]'::jsonb,'SELECT p.publisher_id,p.name AS publisher_name,(SELECT COUNT(*) FROM books b WHERE b.publisher_id=p.publisher_id) AS book_count FROM publishers p WHERE (SELECT COUNT(*) FROM books b WHERE b.publisher_id=p.publisher_id)>(SELECT AVG(t.book_count) FROM (SELECT p2.publisher_id,COUNT(b2.book_id) AS book_count FROM publishers p2 LEFT JOIN books b2 ON b2.publisher_id=p2.publisher_id GROUP BY p2.publisher_id) t) ORDER BY p.publisher_id',29 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
INSERT INTO practice_exercises (id,database_id,title,description,difficulty,topics,max_score,requirements,expected_columns,solution_query,sort_order) SELECT '79a2b2eb-435e-5ee6-8d98-d13c00a5d813',d.id,'Tác giả có ít nhất một sách nhưng không có sách hết hàng','Dùng EXISTS để yêu cầu tác giả có sách, kết hợp NOT EXISTS để loại tác giả có bất kỳ sách nào stock_quantity bằng 0; sắp xếp author_id tăng dần. Trả về các cột theo đúng thứ tự: author_id, author_name.','HARD','SUBQUERY, EXISTS, NOT EXISTS',100,'["Dùng EXISTS để yêu cầu tác giả có sách, kết hợp NOT EXISTS để loại tác giả có bất kỳ sách nào stock_quantity bằng 0; sắp xếp author_id tăng dần.", "Đặt tên và thứ tự cột đúng như yêu cầu.", "Sắp xếp kết quả theo ORDER BY được nêu trong đề bài."]'::jsonb,'["author_id", "author_name"]'::jsonb,'SELECT a.author_id,a.full_name AS author_name FROM authors a WHERE EXISTS (SELECT 1 FROM book_authors ba WHERE ba.author_id=a.author_id) AND NOT EXISTS (SELECT 1 FROM book_authors ba JOIN books b ON b.book_id=ba.book_id WHERE ba.author_id=a.author_id AND b.stock_quantity=0) ORDER BY a.author_id',30 FROM practice_databases d WHERE d.slug='quan-ly-sach-va-tac-gia' ON CONFLICT (id) DO NOTHING;
